where.if:
AND EXISTS (
SELECT 1 FROM SYS_Participant_Unit spu
WHERE spu.C_Id = u.C_ID AND spu.P_Id = #{params.pId}
)

and (u.u_class is null or u.u_class not in

    #{item}
)

mapper.select:
select
p.PL_Name as plName,
c.C_Name as cName,

from SYS_User u
left join SYS_PositionLV p on u.PL_ID=p.PL_ID
left join SYS_Company c on u.C_ID=c.C_ID


    
        order by p.PL_Name ${params.sortType}
    
    
        order by u.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by u.U_CreateTime DESC
    

limit #{params.start},#{params.size}

select
p.PL_Name as plName,
c.C_Name as cName,


from SYS_User u
left join SYS_PositionLV p on u.PL_ID=p.PL_ID
left join SYS_Company c on u.C_ID=c.C_ID


    
        order by p.PL_Name ${params.sortType}
    
    
        order by u.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by u.U_CreateTime DESC
    

limit #{params.start},#{params.size}

select p.P_ID as pId, p.D_ID as dId, p.P_Name as pName, d.D_Name as dName, c.C_Name as cName, plv.PL_Name as plName, pu.Pu_Id as puId, pu.PU_Sort as puSort, pu.PU_Main_Duty as puMainDuty, pu.Pu_Duty as puDuty, pu.Pu_Main_Dep as puMainDep, d.D_ParentID as dParentId,
from SYS_User u left join SYS_Position_User pu on u.U_ID=pu.U_ID left join SYS_Position p on pu.P_ID=p.P_ID left join SYS_Department d on d.D_ID=p.D_ID left join SYS_Company c on c.C_ID=u.C_ID left join SYS_PositionLV plv on plv.PL_ID=u.PL_ID where 1=1
order by plv.PL_Name ${params.sortType}
order by u.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by puSort ASC
order by u.U_CreateTime DESC
limit #{params.start},#{params.size}

select p.P_ID as pId, p.D_ID as dId, p.P_Name as pName, d.D_Name as dName, c.C_Name as cName, plv.PL_Name as plName, pu.Pu_Id as puId, pu.Pu_Sort as puSort,
from SYS_User u left join SYS_Position_User pu on u.U_ID=pu.U_ID left join SYS_Position p on pu.P_ID=p.P_ID left join SYS_Department d on d.D_ID=p.D_ID left join SYS_Company c on c.C_ID=u.C_ID left join SYS_PositionLV plv on plv.PL_ID=u.PL_ID
and u.Te_ID=#{params.teId}
and d.D_ID=#{params.dId}
and u.U_ID=#{params.uId}
and pu.Pu_ID is not null
and INSTR(u.U_Name,#{params.uName})
and INSTR(u.U_Account,#{params.uAccount})
order by u.${sortFiled} ${sortType}
order by pu.Pu_Sort ASC
order by u.U_Sort ASC

select p.PP_ID as ppId, p.PD_ID as pdId, p.PP_Name as ppName, c.C_Name as cName, plv.PL_Name as plName, d.PD_Name as pdName, d.P_Id as projectId, pu.Pup_Id as pupId, pu.Pup_Sort as pupSort,
from SYS_User u left join SYS_Position_User_P pu on u.U_ID=pu.U_ID left join SYS_Position_P p on pu.PP_ID=p.PP_ID left join SYS_Department_P d on d.PD_ID=p.PD_ID left join SYS_Company c on c.C_ID=u.C_ID left join SYS_PositionLV plv on plv.PL_ID=u.PL_ID
and u.Te_Id = #{params.teId}
and d.P_Id in
#{projectId}
and p.PP_Name in
#{ppName}

select table_name
from information_schema.columns
where column_name = 'Con_Id';

select table_name
from information_schema.columns
where column_name = 'Con_Id';

select dp.P_Id as projectId, pp.PP_Name as ppName, u.* from SYS_User u left join SYS_Position_User_P up on up.U_ID=u.U_ID left join SYS_Position_P pp on up.PP_ID=pp.PP_ID left join SYS_Department_P dp on dp.PD_ID=pp.PD_ID where 1=1
and u.Te_Id = #{teId}
and dp.P_Id in
#{projectId}
and pp.PP_Name in
#{posName}
